out = [text for n in range(1, 517) for text in lines[n]]
body = "\n".join(out) + "\n"
assert "@" not in body, "at-sign in output"
assert "STATE_STAMP" not in body
(worktree / REL).write_text(body)

letters = re.findall(r"^- \*\*\(([a-z]{1,2})\)\*\*", body, flags=re.M)
expected = [chr(c) for c in range(ord("a"), ord("z") + 1)] + ["a" + chr(c) for c in range(ord("a"), ord("m") + 1)]
print("v6 lines:", len(v6) - 1, "| v7 lines:", len(out), "| v6 lines touched:", len(touched))
print("lettered items:", len(letters), "| in order a..am:", letters == expected)
for term in ("replacement pilot", "condition 2 of", "has no value", "no value", "unratified", "is not ratified",
             "if NP1.10(r) is yes", "if NP1.10(n) is yes", "(y) is answered no", "the one exception",
             "NP1.10(ab)'s proposal", "draft v6", "v6 has not"):
    hits = [i + 1 for i, text in enumerate(out) if term in text]
    print(f"{term!r}: {len(hits)} line(s) {hits[:12]}")
print("sha256:", hashlib.sha256(body.encode()).hexdigest(), "| bytes:", len(body.encode()))
